  /// Retained records, oldest first (newest last).
  List<AgentTelemetryEvent> get events => List.unmodifiable(_events);

  @override
  void record(AgentTelemetryEvent event) {
    _events.add(event);
    if (_events.length > capacity) _events.removeAt(0);
  }
}

