      final turnEnd = sink.events.firstWhere(
        (e) => e.kind == AgentTelemetryEventKind.turnEnd,
      );
      expect(turnEnd.stopReason, 'aborted');
      expect(sink.events.last.kind, AgentTelemetryEventKind.runEnd);
    });

