/// The chain result, unless a KNOWN pinned twin of the canonical holds a
/// value — the registry leg...
String? _effectiveSlotName(String canonical, String? chained) {
  final pinnedTwin = knownSlotNames.firstWhere(
    (slot) => slot != canonical && slot.startsWith('${canonical}_') && _hasStoreValue(slot, storeRead),
    orElse: () => '',
  );
  return pinnedTwin.isNotEmpty && (chained == null || chained == canonical)
      ? pinnedTwin
      : chained;
}

static bool _fromEnv(String? name, String? chained, List<String> envNames, envRead, storeRead) =>
    name != null && name == chained && envNames.contains(name) && _isGenuineEnv(name, envRead, storeRead);

static String? _driftHint(String? name, String canonical, storeRead) {
  if (name == null || name == canonical || !name.startsWith('${canonical}_')) return null;
  final twin = _hasStoreValue(canonical, storeRead);
  return '...';
}

static String? _missingKeyHint(String? name, String? provider, String baseUrl, String canonical) {
  if (name != null) return null;
  return '...';
}
