    case P.d:
      return 4;
  }
}

int probeSwitchExpression(P p) => switch (p) {
  P.a => 1,
  P.b => 2,
  P.c => 3,
  P.d => 4,
};

int probeStackedCases(P p) {
  switch (p) {
    case P.a:
    case P.b:
      return 1;
    case P.c:
    case P.d:
      return 2;
  }
}

int probeLogicalOr(bool a, bool b, bool c, bool d) =>
    a || b || c || d ? 1 : 0;

int probeCollectionIf(bool a, bool b) => [if (a) 1, if (b) 2].length;

int probeLoopCatch(List<int> xs) {
  var n = 0;
  for (final x in xs) {
    n += x;
  }
  try {
    n ~/= 0;
  } catch (_) {
    n = 0;
  }
  return n;
}

int probeWhenGuard(P p, bool flag) {
  var n = 0;
  switch (p) {
    case P.a when flag:
      n = 1;
    default:
      n = 2;
  }
  return n;
}
