String? _effectiveSlotName(String canonical, String? chained) {
  final pinnedTwin = knownSlotNames.firstWhere(
    (slot) => slot != canonical && slot.startsWith('${canonical}_') && _hasStoreValue(slot, storeRead),
    orElse: () => '',
  );
  return pinnedTwin.isNotEmpty && (chained == null || chained == canonical)
