    fromEnv: _fromEnv(name, chained, envNames, envRead, storeRead),
    canonicalName: canonical,
    driftHint: _driftHint(name, canonical, storeRead),
    missingKeyHint: _missingKeyHint(name, provider, baseUrl, canonical),
