    // Tool supervision events are a family of their own (and the switch
    // below stays under the CRAP ratchet by keeping them out).
    if (event is ToolExecutionStartEvent ||
        event is ToolExecutionEndEvent ||
        event is ToolCallHeartbeatEvent ||
        event is ToolCallStuckEvent) {
      _recordToolEvent(event);
      return;
    }
    switch (event) {
      case AgentStartEvent():
        _runStart = DateTime.now();
        _sawFirstToken = false;
        _lastHttpStatus = null;
        _emit(AgentTelemetryEventKind.runStart);
      case TurnStartEvent():
        _emit(AgentTelemetryEventKind.turnStart);
      case MessageUpdateEvent() when !_sawFirstToken:
        // The agent loop's first streamed update — the provider answered.
        _sawFirstToken = true;
        _emit(
          AgentTelemetryEventKind.firstToken,
          detail: _modelDetail(_agent?.state.model),
        );
      case TurnEndEvent(:final message):
        _emit(
          AgentTelemetryEventKind.turnEnd,
          stopReason: message.stopReason.name,
        );
      case AgentEndEvent():
        _recordAgentEnd(event);
      default:
      // MessageStart/End, ModelRequest, pairing repair, partial
      // updates — per-message detail the CLI also keeps out of fa.log.
    }
  }

  /// The four tool-execution phases the CLI logs (`tool start`/`tool end`/
  /// heartbeat/stuck), one record each.
  void _recordToolEvent(AgentEvent event) {
    switch (event) {
      case ToolExecutionStartEvent(:final toolCallId, :final toolName):
        _emit(
          AgentTelemetryEventKind.toolStart,
          toolCallId: toolCallId,
          toolName: toolName,
        );
      case ToolExecutionEndEvent(
        :final toolCallId,
        :final toolName,
        :final isError,
      ):
        _emit(
          AgentTelemetryEventKind.toolEnd,
          toolCallId: toolCallId,
          toolName: toolName,
          isError: isError,
        );
      case ToolCallHeartbeatEvent(
        :final toolCallId,
        :final toolName,
        :final elapsed,
        :final outputBytes,
        :final attempt,
      ):
        _emit(
          AgentTelemetryEventKind.toolHeartbeat,
          toolCallId: toolCallId,
          toolName: toolName,
          outputBytes: outputBytes,
          attempt: attempt,
          detail: 'elapsed=${elapsed.inSeconds}s',
        );
      case ToolCallStuckEvent(
        :final toolCallId,
        :final toolName,
        :final action,
        :final elapsed,
      ):
        _emit(
          AgentTelemetryEventKind.toolStuck,
          toolCallId: toolCallId,
          toolName: toolName,
          detail: 'action=${action.name} elapsed=${elapsed.inSeconds}s',
        );
      default:
        break; // Not a tool event — unreachable through _record.
    }
  }

  /// The run terminal: a provider failure emits the `error` record first
  /// (with the captured HTTP status); every run then closes with `run end`.
  void _recordAgentEnd(AgentEndEvent event) {
    final error = agentErrorMessage(event);
    if (error != null) {
      _emit(
        AgentTelemetryEventKind.error,
        httpStatus: _lastHttpStatus,
        detail: error,
      );
    }
    // Aborted runs (user stop, watchdog fire) are NOT errors — the
    // CLI's fa.log records them as a plain `run end` with the turn's
    // `stop=aborted` carrying the distinction; mirror that.
    _emit(AgentTelemetryEventKind.runEnd);
  }"}

{"newText":"  HostKeyResolution resolveKey({
    String? provider,
    required String baseUrl,
    String? model,
    List<String> envNames = const [],
    String? defaultBaseUrl,
    String? activeCustomKeyName,
  }) {
    // The HOST-scoped canonical (no provider-name suffix) — the same slot
    // resolveEndpointKeyName probes, so the drift comparison is
    // like-for-like.
    final canonical = CustomProviderRegistry.keyNameFor(baseUrl);
    final chained = resolveEndpointKeyName(
      envNames: envNames,
      defaultBaseUrl: defaultBaseUrl,
      baseUrl: baseUrl,
      envRead: envRead,
      storeRead: storeRead,
      activeCustomKeyName: activeCustomKeyName,
    );
    final name = _effectiveSlotName(canonical, chained);
    return HostKeyResolution(
      slotName: name,
      fromEnv: _isEnvResolution(name, chained, envNames),
      canonicalName: canonical,
      driftHint: _driftHint(name, canonical),
      missingKeyHint: _missingKeyHint(name, provider, baseUrl, canonical),
    );
  }

  /// The chain result, unless a KNOWN pinned twin of the canonical holds a
  /// value — the registry leg. A pinned twin keeps winning while the chain
  /// landed on the canonical (or nothing), exactly like the CLI's saved
  /// entries pin their own slots — this is what turns the issue's kimi
  /// trap into a working binding plus a visible warning.
  String? _effectiveSlotName(String canonical, String? chained) {
    final pinnedTwin = knownSlotNames.firstWhere(
      (slot) =>
          slot != canonical &&
          slot.startsWith('${canonical}_') &&
          _hasStoreValue(slot, storeRead),
      orElse: () => '',
    );
    final twinWins = pinnedTwin.isNotEmpty && (chained == null ||
        chained == canonical);
    return twinWins ? pinnedTwin : chained;
  }

  /// Whether [name] was resolved from the process environment (the env
  /// leg of the chain — a genuine env value, not a store echo).
  bool _isEnvResolution(String? name, String? chained, List<String> envNames) =>
      name != null &&
      name == chained &&
      envNames.contains(name) &&
      _isGenuineEnv(name, envRead, storeRead);

  /// The CLI's pinned-slot drift hint, non-null when [name] is a pinned
  /// twin of the canonical (`<canonical>_…`).
  String? _driftHint(String? name, String canonical) {
    if (name == null || name == canonical) return null;
    if (!name.startsWith('${canonical}_')) return null;
    final twin = _hasStoreValue(canonical, storeRead);
