  // outlive the run (they would pin the host's process at exit).
  if (runToken != null) {
    unawaited(
      runToken.onCancel.then((_) {
        clock.disarm();
        callSource.cancel(runToken.cancelReason);
        if (!clock.graceGate.isCompleted) clock.graceGate.complete();
