          AgentTelemetryEventKind.toolStart,
          toolCallId: toolCallId,
          toolName: toolName,
        );
      case ToolExecutionEndEvent(
        :final toolCallId,
        :final toolName,
        :final isError,
      ):
        _emit(
          AgentTelemetryEventKind.toolEnd,
          toolCallId: toolCallId,
          toolName: toolName,
          isError: isError,
        );
      case ToolCallHeartbeatEvent(
        :final toolCallId,
        :final toolName,
        :final elapsed,
        :final outputBytes,
        :final attempt,
      ):
        _emit(
          AgentTelemetryEventKind.toolHeartbeat,
          toolCallId: toolCallId,
          toolName: toolName,
          outputBytes: outputBytes,
          attempt: attempt,
          detail: 'elapsed=${elapsed.inSeconds}s',
        );
      case ToolCallStuckEvent(
        :final toolCallId,
        :final toolName,
        :final action,
        :final elapsed,
      ):
        _emit(
          AgentTelemetryEventKind.toolStuck,
          toolCallId: toolCallId,
          toolName: toolName,
          detail: 'action=${action.name} elapsed=${elapsed.inSeconds}s',
        );
      default:
        break; // Not a tool event — unreachable through _record.
    }
  }

  /// The run terminal: a provider failure emits the `error` record first
  /// (with the captured HTTP status); every run then closes with `run end`.
  void _recordAgentEnd(AgentEndEvent event) {
    final error = agentErrorMessage(event);
    if (error != null) {
      _emit(
        AgentTelemetryEventKind.error,
        httpStatus: _lastHttpStatus,
        detail: error,
