          toolCallId: toolCallId,
          toolName: toolName,
          isError: isError,
        );
      case ToolCallHeartbeatEvent(
        :final toolCallId,
        :final toolName,
        :final elapsed,
        :final outputBytes,
        :final attempt,
      ):
        _emit(
          AgentTelemetryEventKind.toolHeartbeat,
          toolCallId: toolCallId,
          toolName: toolName,
          outputBytes: outputBytes,
          attempt: attempt,
          detail: 'elapsed=${elapsed.inSeconds}s',
        );
      case ToolCallStuckEvent(
        :final toolCallId,
        :final toolName,
        :final action,
        :final elapsed,
      ):
        _emit(
          AgentTelemetryEventKind.toolStuck,
          toolCallId: toolCallId,
