String? resolveEndpointKeyName({...}) {
  final defaultEndpoint = defaultBaseUrl != null && baseUrl == defaultBaseUrl;
  if (defaultEndpoint) {
    final genuine = _firstGenuineEnvName(envNames, envRead, storeRead);
    if (genuine != null) return genuine;
  }
  final pinned = _pinnedSlotName(defaultEndpoint, activeCustomKeyName, storeRead);
  if (pinned != null) return pinned;
  final scoped = CustomProviderRegistry.keyNameFor(baseUrl);
  if (_hasStoreValue(scoped, storeRead)) return scoped;
  if (defaultEndpoint) return _legacyEnvSlotName(envNames, storeRead);
  return null;
}

/// The active custom entry's own pinned slot (non-default endpoints only —
/// the host-scoped entry wins there).
static String? _pinnedSlotName(bool defaultEndpoint, String? activeCustomKeyName, storeRead) {
  if (defaultEndpoint || activeCustomKeyName == null) return null;
  return _hasStoreValue(activeCustomKeyName, storeRead) ? activeCustomKeyName : null;
}

static String? _legacyEnvSlotName(List<String> envNames, storeRead) {
  for (final name in envNames) {
    if (_hasStoreValue(name, storeRead)) return name;
  }
  return null;
}
