  void _record(AgentEvent event) => switch (event) {
    // Tool supervision events are a family of their own (and the run-phase
    // switch below stays under the CRAP ratchet by keeping them out).
    ToolExecutionStartEvent() ||
    ToolExecutionEndEvent() ||
    ToolCallHeartbeatEvent() ||
    ToolCallStuckEvent() => _recordToolEvent(event),
    _ => _recordRunPhase(event),
  };

  void _recordRunPhase(AgentEvent event) {
    switch (event) {
      case AgentStartEvent():
        _runStart = DateTime.now();
        _sawFirstToken = false;
        _lastHttpStatus = null;
        _emit(AgentTelemetryEventKind.runStart);
      case TurnStartEvent():
        _emit(AgentTelemetryEventKind.turnStart);
      case MessageUpdateEvent() when !_sawFirstToken:
        // The agent loop's first streamed update — the provider answered.
        _sawFirstToken = true;
        _emit(
          AgentTelemetryEventKind.firstToken,
          detail: _modelDetail(_agent?.state.model),
        );
      case TurnEndEvent(:final message):
        _emit(
          AgentTelemetryEventKind.turnEnd,
          stopReason: message.stopReason.name,
        );
      case AgentEndEvent():
        _recordAgentEnd(event);
      default:
      // MessageStart/End, ModelRequest, pairing repair, partial
      // updates — per-message detail the CLI also keeps out of fa.log.
    }
  }

  /// The four tool-execution phases the CLI logs (`tool start`/`tool end`/
  /// heartbeat/stuck), one record each.
  void _recordToolEvent(AgentEvent event) {
    switch (event) {
      case ToolExecutionStartEvent(:final toolCallId, :final toolName):
        _emit(
          AgentTelemetryEventKind.toolStart,
          toolCallId: toolCallId,
          toolName: toolName,
        );
      case ToolExecutionEndEvent(
        :final toolCallId,
        :final toolName,
        :final isError,
      ):
        _emit(
          AgentTelemetryEventKind.toolEnd,
          toolCallId: toolCallId,
          toolName: toolName,
          isError: isError,
        );
      case ToolCallHeartbeatEvent(
        :final toolCallId,
        :final toolName,
        :final elapsed,
        :final outputBytes,
        :final attempt,
      ):
        _emit(
          AgentTelemetryEventKind.toolHeartbeat,
          toolCallId: toolCallId,
          toolName: toolName,
          outputBytes: outputBytes,
          attempt: attempt,
          detail: 'elapsed=${elapsed.inSeconds}s',
        );

